cat > /workspace/scratch/gen_randfuzz.awk <<'AWKEOF'
# Generator 1: dense-random printable ASCII, lengths 0..40
BEGIN {
    srand(20260808);
    # build weighted alphabet
    A = "";
    A = A "::::::::::::";            # 12 colons
    A = A "////////////////";        # 16 slashes
    A = A "?????????";               # 9
    A = A "#########";               # 9
    A = A "@@@@@@@@@";               # 9
    A = A "00112233445566778899";    # 20 digits
    A = A "0123456789";              # 10 more digits
    A = A "abcdefghijklmnopqrstuvwxyz";
    A = A "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    A = A "aehlmoprstwx";            # extra common scheme/host letters
    A = A ".....";                   # 5 dots
    A = A "---";
    A = A "___";
    A = A "%%%";
    A = A "   ";                     # 3 spaces
    A = A "==";
    A = A "&&";
    A = A ";;";
    A = A "++";
    A = A ",,";
    A = A "~!$()*'";
    A = A "[]<>\"\\|^`{}";
    A = A "\t";
    n = length(A);
    N = (NCASES == "" ? 40000 : NCASES+0);
    for (i = 0; i < N; i++) {
        L = int(rand() * 41);        # 0..40
        s = "";
        for (j = 0; j < L; j++) {
            k = int(rand() * n) + 1;
            s = s substr(A, k, 1);
        }
        print s;
    }
}
AWKEOF
awk -f /workspace/scratch/gen_randfuzz.awk > /workspace/scratch/randfuzz_A.txt
wc -l /workspace/scratch/randfuzz_A.txt; head -12 /workspace/scratch/randfuzz_A.txt | cat -A | head -12

cd /workspace/scratch && awk -v NCASES=40000 -f gen_randfuzz.awk > /dev/null 2>&1; \
cat > gen_randfuzz2.awk <<'AWKEOF'
BEGIN {
    srand(SEED+0);
    if (MODE == "sig") {
        A = ":/?#@0123456789ab .%:/?#@";   # significant chars dominate
        LO = 0; HI = 13;
    } else if (MODE == "long") {
        A = "::::////????####@@@@0123456789abcdefghijklmnopqrstuvwxyzABCXYZ.-_%+=&; ~!$()*'[]<>\"\\|^`{},";
        LO = 40; HI = 121;
    } else {
        A = ":::::::::://////////????????########@@@@@@@@0011223344556677889901234567890abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ.....---___%%%   ==&&;;++,,~!$()*'[]<>\"\\|^`{}\t";
        LO = 0; HI = 41;
    }
    n = length(A);
    N = NCASES+0;
    for (i = 0; i < N; i++) {
        L = LO + int(rand() * (HI - LO));
        s = "";
        for (j = 0; j < L; j++) s = s substr(A, int(rand()*n)+1, 1);
        print s;
    }
}
AWKEOF
awk -v SEED=777001 -v MODE=sig  -v NCASES=40000 -f gen_randfuzz2.awk > randfuzz_C.txt
awk -v SEED=777002 -v MODE=long -v NCASES=10000 -f gen_randfuzz2.awk > randfuzz_D.txt
awk -v SEED=777003 -v MODE=std  -v NCASES=40000 -f gen_randfuzz2.awk > randfuzz_E.txt
wc -l randfuzz_C.txt randfuzz_D.txt randfuzz_E.txt
echo "--- C sample"; head -6 randfuzz_C.txt; echo "--- D sample"; head -2 randfuzz_D.txt; echo "--- E sample"; head -4 randfuzz_E.txt
